/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to Discounts and add entry to Price Change tracking table 
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeEvent))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, DiscountEnabled))]
public class METPriceChangeEventDiscountEnabled extends METPriceChangeEvent
{
    RetailPeriodicDiscount  retailPeriodicDiscount;
        
}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void initInstance(Common _common, SysAppCRUDOperation _crud)
{
    this.setInternals(_Common, _crud);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void setInternals(Common _common, SysAppCRUDOperation _crud)
{
    super(_common, _crud);
    retailPeriodicDiscount = _common as retailPeriodicDiscount;
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::DiscountEnabled;
}

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    public void process()
    {

        if(retailPeriodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer)
        {
            this.processSingle(qtyOne);
        }
        else if (retailPeriodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Multibuy)
        {
            this.processQuantity();
        }
        
        ttsbegin;
        priceChangeTrackingList.insertDatabase();
        ttscommit;
    }

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    /// <param name = "_fromQty">From Quantity</param>
    public void processSingle(RetailQtyLowest _fromQty)
    {
        FromDate                    fromDate;
        RetailQtyLowest             fromQty;

        fromDate = this.getFromDate(retailPeriodicDiscount.ValidFrom);
        fromQty = this.getFromQty(_fromQty);

        this.cleanup(fromDate, fromQty);
        this.processTrans(fromDate, fromQty);
        priceChangeTrackingList.add(priceChangeTracking);

    }

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    public void processQuantity()
    {
        RetailMultibuyDiscountLine  retailMultibuyDiscountLine;

        while select qtyLowest
            from    retailMultibuyDiscountLine
            where   retailMultibuyDiscountLine.multibuyId == retailPeriodicDiscount.OfferId
        {
            this.processSingle(retailMultibuyDiscountLine.qtyLowest);
        }
    }

/// <summary>
/// Process the base record that triggered the change and create Price Change Track record
/// </summary>
/// <param name = "_fromDate">From Date</param>
/// <param name = "_fromQty">From Quantity</param>
public void processTrans(FromDate _fromDate, RetailQtyLowest _fromQty)
{
    priceChangeTracking.clear();
    this.setCommonValues(retailPeriodicDiscount);
    priceChangeTracking.pricingRuleHeader       = retailPeriodicDiscount.HeaderPricingRule;
    priceChangeTracking.DiscountCode            = retailPeriodicDiscount.offerId;
    priceChangeTracking.ToDate                  = retailPeriodicDiscount.ValidTo;
    priceChangeTracking.Activation              = NoYes::Yes;
    priceChangeTracking.QuantityAmountFrom      = _fromQty;
    priceChangeTracking.FromDate                = _fromDate;
}

    /// <summary>
    /// remove existing records to avoid duplicate processing and churn
    /// </summary>
    /// <param name = "_fromDate">from date</param>
    /// <param name = "_fromQty">qty from</param>
    public void cleanup(FromDate _fromDate, RetailQtyLowest _fromQty)
    {
        METPriceChangeTracking      priceChangeTrackingLoc;
        
        //if a record of the same type exists remove it.
        ttsbegin;
        
        delete_from priceChangeTrackingLoc
            where   priceChangeTrackingLoc.DiscountCode    == retailPeriodicDiscount.OfferId
            &&      priceChangeTrackingLoc.FromDate        == _fromDate
            &&      priceChangeTrackingLoc.QuantityAmountFrom  == _fromQty
            &&      priceChangeTrackingLoc.ChangeType      == this.getPriceChangeType()
            &&      priceChangeTrackingLoc.Activation      == NoYes::Yes;

        ttscommit;
    }
